<?php require_once __DIR__ . '/Model.php'; class SettingsModel extends Model { protected $table = 'settings'; public function get($key, $default = null) { $st = db()->prepare('SELECT setting_value FROM settings WHERE setting_key = ?'); $st->execute([$key]); $r = $st->fetch(); return $r ? $r['setting_value'] : $default; } public function set($key, $value) { db()->prepare('INSERT INTO settings (setting_key, setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$key, $value]); } } 